#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_text_is_looked_up_by_its_english_and_filled() {
        assert_eq!(
            fill("Closed {0} of {1}", &[&"a.log", &3]),
            "Closed a.log of 3"
        );
        assert_eq!(tx(Language::En, "Wrong PIN"), "Wrong PIN");
    }

    #[test]
    fn every_terminal_text_is_translated() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src/tui");
        let call = regex::Regex::new(r#"\b(?:txf?\(\s*[a-z_.()]+,\s*|en\(\s*)"((?:[^"\\]|\\.)*)""#)
            .unwrap();
        let mut missing = Vec::new();
        for entry in std::fs::read_dir(dir).unwrap() {
            let path = entry.unwrap().path();
            let text = std::fs::read_to_string(&path).unwrap();
            for c in call.captures_iter(&text) {
                let en = c[1].replace("\\\"", "\"").replace("\\\\", "\\");
                if !table().contains_key(en.as_str()) {
                    missing.push(format!("{}: {en}", path.display()));
                }
            }
        }
        missing.sort();
        missing.dedup();
        assert!(
            missing.is_empty(),
            "texts without a translation row: {missing:#?}"
        );
        // No row repeats, and every translation keeps the places of its English.
        let mut seen = std::collections::HashSet::new();
        for (en, row) in TEXTS {
            assert!(seen.insert(en), "row twice: {en}");
            for (i, t) in row.iter().enumerate() {
                for n in 0..4 {
                    let place = format!("{{{n}}}");
                    assert_eq!(
                        en.contains(&place),
                        t.contains(&place),
                        "{en} / {:?}: {t}",
                        Language::ALL[i + 1]
                    );
                }
            }
        }
    }
}
